{"content":"# -*- coding: utf-8 -*-
"""把 F(...)/G(...) 调用内的参数行规整为合法的逗号分隔列表。

规则（只处理调用内、以引号或常量开头的行）：
- 若上一行是 F(/G( 开头或已以 ','/'(' 结尾，则本行保持原样；
- 否则在本行结尾补 ','（若本行不是最后一行参数）。
"""
import re, sys

path = sys.argv[1]
lines = open(path, encoding="utf-8").read().split("\n")
starts = [i for i, l in enumerate(lines) if re.match(r"^[FG]\(", l.strip())]
print("calls:", len(starts))

out = list(lines)
inside = False
for i, raw in enumerate(lines):
    s = raw.strip()
    if not inside:
        if re.match(r"^[FG]\(", s):
            inside = True
        continue
    if s.startswith(")"):
        inside = False
        continue
    nxt = lines[i + 1].strip() if i + 1 < len(lines) else ""
    if nxt.startswith(")") or nxt == "":
        continue
    if s.startswith("+") or s.endswith(","):
        continue
    out[i] = raw.rstrip() + ","
# 剥除所有残留的行首 '+'
for i, raw in enumerate(out):
    m = re.match(r"^(\s*)\+\s*(.*)$", raw)
    if m and inside_or_call(lines, i):
        out[i] = m.group(1) + m.group(2)
open(path, "w", encoding="utf-8").write("\n".join(out))
print("done")


def inside_or_call(lines, idx):
    for j in range(idx, -1, -1):
        s = lines[j].strip()
        if re.match(r"^[FG]\(", s):
            return True
        if s.startswith(")"):
